'use strict';
const lines=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
function outcome(b){for(const line of lines){if(b[line[0]]&&line.every(i=>b[i]===b[line[0]]))return {winner:b[line[0]],line};}return b.every(Boolean)?{winner:'draw',line:[]}:null;}
function chooseMove(b,smart){const empty=b.map((v,i)=>v?null:i).filter(i=>i!==null);if(!empty.length)return null;if(smart){for(const who of ['O','X'])for(const i of empty){const next=b.slice();next[i]=who;if(outcome(next)?.winner===who)return i;}if(empty.includes(4))return 4;const corners=empty.filter(i=>[0,2,6,8].includes(i));if(corners.length)return corners[Math.floor(Math.random()*corners.length)];}return empty[Math.floor(Math.random()*empty.length)];}
function alien(blue=false,small=false){const c=blue?'#65d6ff':'#ffb154',shade=blue?'#237fcb':'#e86b30';return `<svg viewBox="0 0 220 220" aria-hidden="true"><defs><radialGradient id="${blue?'b':'a'}${small?'s':''}"><stop stop-color="${c}"/><stop offset="1" stop-color="${shade}"/></radialGradient></defs><ellipse cx="110" cy="202" rx="58" ry="9" fill="#000" opacity=".18"/><path d="M83 65 68 33M137 65l15-32" stroke="${c}" stroke-width="9" stroke-linecap="round"/><circle cx="66" cy="29" r="12" fill="${c}"/><circle cx="154" cy="29" r="12" fill="${c}"/><ellipse cx="110" cy="165" rx="46" ry="37" fill="${shade}"/><ellipse cx="72" cy="192" rx="24" ry="13" fill="${c}"/><ellipse cx="148" cy="192" rx="24" ry="13" fill="${c}"/><path d="M69 150Q37 166 32 140M151 150q32 16 37-10" fill="none" stroke="${c}" stroke-width="17" stroke-linecap="round"/><path d="M30 96Q20 44 59 77M190 96q10-52-29-19" fill="${shade}"/><ellipse cx="110" cy="108" rx="79" ry="65" fill="url(#${blue?'b':'a'}${small?'s':''})"/><ellipse cx="79" cy="102" rx="25" ry="31" fill="#fff9ed"/><ellipse cx="141" cy="102" rx="25" ry="31" fill="#fff9ed"/><ellipse cx="84" cy="106" rx="14" ry="21" fill="#142a49"/><ellipse cx="136" cy="106" rx="14" ry="21" fill="#142a49"/><circle cx="89" cy="98" r="6" fill="white"/><circle cx="141" cy="98" r="6" fill="white"/><ellipse cx="58" cy="133" rx="13" ry="7" fill="#ff6580" opacity=".4"/><ellipse cx="162" cy="133" rx="13" ry="7" fill="#ff6580" opacity=".4"/><path d="M91 140Q110 161 129 140" fill="#582e40" stroke="#582e40" stroke-width="4" stroke-linecap="round"/><path d="M101 144h18" stroke="white" stroke-width="5" stroke-linecap="round"/><ellipse cx="108" cy="173" rx="14" ry="10" fill="${c}"/><text x="110" y="180" text-anchor="middle" font-family="Arial" font-weight="bold" font-size="20" fill="#19304b">${blue?'O':'X'}</text></svg>`;}
if(typeof document!=='undefined'){
let board,thinking=false,finished=false,timer,scores={wins:0,draws:0,losses:0};
try{const saved=JSON.parse(localStorage.getItem('alienScores'));if(saved)for(const k of Object.keys(scores))if(Number.isSafeInteger(saved[k])&&saved[k]>=0)scores[k]=saved[k];}catch{}
const status=document.getElementById('status'),grid=document.getElementById('board');
document.getElementById('orange-alien').innerHTML=alien();document.getElementById('blue-alien').innerHTML=alien(true);
const cells=Array.from({length:9},(_,i)=>{const cell=document.createElement('button');cell.className='cell';cell.addEventListener('click',()=>play(i));grid.append(cell);return cell;});
function score(){for(const k of Object.keys(scores))document.getElementById(k).textContent=scores[k];try{localStorage.setItem('alienScores',JSON.stringify(scores));}catch{}}
function render(){cells.forEach((cell,i)=>{cell.innerHTML=board[i]?alien(board[i]==='O',true):'';cell.disabled=!!board[i]||thinking||finished;cell.setAttribute('aria-label',`Row ${Math.floor(i/3)+1}, column ${i%3+1}: ${board[i]==='X'?'your alien X':board[i]==='O'?'Nova O':'empty'}`);});}
function finish(){const result=outcome(board);if(!result)return false;finished=true;thinking=false;const key=result.winner==='X'?'wins':result.winner==='O'?'losses':'draws';scores[key]++;score();status.textContent=result.winner==='X'?'You win! Stellar moves!':result.winner==='O'?'Nova wins! Rematch, explorer?':'A cosmic tie! Well played.';render();result.line.forEach(i=>cells[i].classList.add('winner'));return true;}
function play(i){if(thinking||finished||board[i])return;board[i]='X';if(finish())return;thinking=true;status.textContent='Nova is plotting a cosmic move…';render();timer=setTimeout(()=>{const move=chooseMove(board,document.getElementById('difficulty').value==='smart');if(move!==null)board[move]='O';thinking=false;if(!finish()){status.textContent='Your move, space explorer!';render();}},550);}
function restart(){clearTimeout(timer);board=Array(9).fill(null);thinking=false;finished=false;cells.forEach(c=>c.classList.remove('winner'));status.textContent='Your move, space explorer!';render();}
document.getElementById('restart').addEventListener('click',restart);document.getElementById('difficulty').addEventListener('change',restart);document.getElementById('reset-scores').addEventListener('click',()=>{scores={wins:0,draws:0,losses:0};score();restart();});score();restart();
}
if(typeof module!=='undefined')module.exports={outcome,chooseMove};
